from typing import Dict, Any, List

class StructuredLogEvent:
    def __init__(self, message: str, severity: str, service_name: str, **kwargs):
        self.message = message
        self.severity = severity
        self.service_name = service_name
        self.data = kwargs

    def to_json(self) -> Dict[str, Any]:
        return {
            "message": self.message,
            "severity": self.severity,
            "service_name": self.service_name,
            **self.data
        }

class CorrelatedLogEvent(StructuredLogEvent):
    def __init__(self, message: str, severity: str, service_name: str, correlation_id: str, **kwargs):
        super().__init__(message, severity, service_name, **kwargs)
        self.correlation_id = correlation_id

    def to_json(self) -> Dict[str, Any]:
        base_json = super().to_json()
        base_json["correlation_id"] = self.correlation_id
        return base_json

class LogQueryResult:
    def __init__(self, raw_data: List[Dict[str, Any]]):
        self.raw_data = raw_data

    def get_first_message(self) -> str:
        if self.raw_data and "message" in self.raw_data[0]:
            return self.raw_data[0]["message"]
        return ""

from observability_client import ObservabilityClient

def check_log_safety(log_message: str):
    client = ObservabilityClient()

    if not client.openai_client:
        print("Azure OpenAI client not initialized. Cannot check log safety.")
        return None

    try:
        response = client.openai_client.moderations.create(input=log_message)
        moderation_result = response.results[0]
        return moderation_result

    except Exception as e:
        print(f"Error checking log safety with Azure OpenAI: {e}")
        return None

from observability_client import ObservabilityClient

def translate_log_message(log_message: str, target_language: str = "French"):
    client = ObservabilityClient()

    if not client.openai_client:
        print("Azure OpenAI client not initialized. Cannot translate log message.")
        return ""

    prompt = f"Translate the following log message into {target_language}: '{log_message}'"

    try:
        response = client.openai_client.chat.completions.create(
            model=client.azure_openai_deployment_name,
            messages=[
                {"role": "system", "content": "You are an AI assistant that translates log messages."},
                {"role": "user", "content": prompt}
            ],
            temperature=0.7,
            max_tokens=200
        )
        translated_message = response.choices[0].message.content
        return translated_message

    except Exception as e:
        print(f"Error translating log message with Azure OpenAI: {e}")
        return f"Failed to translate log message due to error: {e}"
